SELECT (SELECT COUNT(*) FROM Countries) AS Countries, (SELECT COUNT(*) FROM DestinationCities) AS Cities, (SELECT COUNT(*) FROM Airports) AS Airports, (SELECT COUNT(*) FROM Airports WHERE CityId IS NOT NULL) AS LinkedAirports, (SELECT COUNT(*) FROM DestinationCities WHERE ImageFile <> N'' AND Description <> N'') AS CitiesWithDetails;
